//! AES-128 decryption (FIPS-197 inverse cipher), only what XEX2 needs:
//! ECB for the file key and CBC with a zero IV for the payload.

const SBOX: [u8; 256] = [
    0x63, 0x7c, 0x77, 0x7b, 0xf2, 0x6b, 0x6f, 0xc5, 0x30, 0x01, 0x67, 0x2b, 0xfe, 0xd7, 0xab, 0x76,
    0xca, 0x82, 0xc9, 0x7d, 0xfa, 0x59, 0x47, 0xf0, 0xad, 0xd4, 0xa2, 0xaf, 0x9c, 0xa4, 0x72, 0xc0,
    0xb7, 0xfd, 0x93, 0x26, 0x36, 0x3f, 0xf7, 0xcc, 0x34, 0xa5, 0xe5, 0xf1, 0x71, 0xd8, 0x31, 0x15,
    0x04, 0xc7, 0x23, 0xc3, 0x18, 0x96, 0x05, 0x9a, 0x07, 0x12, 0x80, 0xe2, 0xeb, 0x27, 0xb2, 0x75,
    0x09, 0x83, 0x2c, 0x1a, 0x1b, 0x6e, 0x5a, 0xa0, 0x52, 0x3b, 0xd6, 0xb3, 0x29, 0xe3, 0x2f, 0x84,
    0x53, 0xd1, 0x00, 0xed, 0x20, 0xfc, 0xb1, 0x5b, 0x6a, 0xcb, 0xbe, 0x39, 0x4a, 0x4c, 0x58, 0xcf,
    0xd0, 0xef, 0xaa, 0xfb, 0x43, 0x4d, 0x33, 0x85, 0x45, 0xf9, 0x02, 0x7f, 0x50, 0x3c, 0x9f, 0xa8,
    0x51, 0xa3, 0x40, 0x8f, 0x92, 0x9d, 0x38, 0xf5, 0xbc, 0xb6, 0xda, 0x21, 0x10, 0xff, 0xf3, 0xd2,
    0xcd, 0x0c, 0x13, 0xec, 0x5f, 0x97, 0x44, 0x17, 0xc4, 0xa7, 0x7e, 0x3d, 0x64, 0x5d, 0x19, 0x73,
    0x60, 0x81, 0x4f, 0xdc, 0x22, 0x2a, 0x90, 0x88, 0x46, 0xee, 0xb8, 0x14, 0xde, 0x5e, 0x0b, 0xdb,
    0xe0, 0x32, 0x3a, 0x0a, 0x49, 0x06, 0x24, 0x5c, 0xc2, 0xd3, 0xac, 0x62, 0x91, 0x95, 0xe4, 0x79,
    0xe7, 0xc8, 0x37, 0x6d, 0x8d, 0xd5, 0x4e, 0xa9, 0x6c, 0x56, 0xf4, 0xea, 0x65, 0x7a, 0xae, 0x08,
    0xba, 0x78, 0x25, 0x2e, 0x1c, 0xa6, 0xb4, 0xc6, 0xe8, 0xdd, 0x74, 0x1f, 0x4b, 0xbd, 0x8b, 0x8a,
    0x70, 0x3e, 0xb5, 0x66, 0x48, 0x03, 0xf6, 0x0e, 0x61, 0x35, 0x57, 0xb9, 0x86, 0xc1, 0x1d, 0x9e,
    0xe1, 0xf8, 0x98, 0x11, 0x69, 0xd9, 0x8e, 0x94, 0x9b, 0x1e, 0x87, 0xe9, 0xce, 0x55, 0x28, 0xdf,
    0x8c, 0xa1, 0x89, 0x0d, 0xbf, 0xe6, 0x42, 0x68, 0x41, 0x99, 0x2d, 0x0f, 0xb0, 0x54, 0xbb, 0x16,
];

fn xtime(x: u8) -> u8 {
    (x << 1) ^ if x & 0x80 != 0 { 0x1b } else { 0 }
}

fn mul(mut a: u8, mut b: u8) -> u8 {
    let mut product = 0;
    while b != 0 {
        if b & 1 != 0 {
            product ^= a;
        }
        a = xtime(a);
        b >>= 1;
    }
    product
}

pub(crate) struct Aes128 {
    round_keys: [[u8; 16]; 11],
    inverse_sbox: [u8; 256],
}

impl Aes128 {
    pub(crate) fn new(key: [u8; 16]) -> Self {
        let mut words = [[0u8; 4]; 44];
        for (i, word) in words.iter_mut().take(4).enumerate() {
            word.copy_from_slice(&key[i * 4..i * 4 + 4]);
        }
        let mut rcon = 1u8;
        for i in 4..44 {
            let mut t = words[i - 1];
            if i % 4 == 0 {
                t = [
                    SBOX[t[1] as usize] ^ rcon,
                    SBOX[t[2] as usize],
                    SBOX[t[3] as usize],
                    SBOX[t[0] as usize],
                ];
                rcon = xtime(rcon);
            }
            for j in 0..4 {
                words[i][j] = words[i - 4][j] ^ t[j];
            }
        }
        let mut round_keys = [[0u8; 16]; 11];
        for (round, key) in round_keys.iter_mut().enumerate() {
            for j in 0..4 {
                key[j * 4..j * 4 + 4].copy_from_slice(&words[round * 4 + j]);
            }
        }
        let mut inverse_sbox = [0u8; 256];
        for (i, &s) in SBOX.iter().enumerate() {
            inverse_sbox[s as usize] = i as u8;
        }
        Self {
            round_keys,
            inverse_sbox,
        }
    }

    pub(crate) fn decrypt_block(&self, block: &mut [u8; 16]) {
        let add = |block: &mut [u8; 16], key: &[u8; 16]| {
            for (b, k) in block.iter_mut().zip(key) {
                *b ^= k;
            }
        };
        add(block, &self.round_keys[10]);
        for round in (0..10).rev() {
            // Inverse ShiftRows (state is column-major: byte r + 4c).
            let s = *block;
            for c in 0..4 {
                for r in 0..4 {
                    block[r + 4 * ((c + r) % 4)] = s[r + 4 * c];
                }
            }
            for b in block.iter_mut() {
                *b = self.inverse_sbox[*b as usize];
            }
            add(block, &self.round_keys[round]);
            if round > 0 {
                for c in 0..4 {
                    let col = [
                        block[4 * c],
                        block[4 * c + 1],
                        block[4 * c + 2],
                        block[4 * c + 3],
                    ];
                    for r in 0..4 {
                        block[4 * c + r] = mul(col[r], 14)
                            ^ mul(col[(r + 1) % 4], 11)
                            ^ mul(col[(r + 2) % 4], 13)
                            ^ mul(col[(r + 3) % 4], 9);
                    }
                }
            }
        }
    }

    /// CBC with a zero IV over whole 16-byte blocks; a trailing partial
    /// block is left untouched.
    pub(crate) fn decrypt_cbc_zero_iv(&self, data: &mut [u8]) {
        let mut previous = [0u8; 16];
        for chunk in data.chunks_exact_mut(16) {
            let cipher: [u8; 16] = chunk.try_into().unwrap();
            let mut block = cipher;
            self.decrypt_block(&mut block);
            for (out, (plain, prev)) in chunk.iter_mut().zip(block.iter().zip(previous)) {
                *out = plain ^ prev;
            }
            previous = cipher;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fips_197_appendix_c1_vector_decrypts() {
        let key: [u8; 16] = core::array::from_fn(|i| i as u8);
        let mut block = [
            0x69, 0xc4, 0xe0, 0xd8, 0x6a, 0x7b, 0x04, 0x30, 0xd8, 0xcd, 0xb7, 0x80, 0x70, 0xb4,
            0xc5, 0x5a,
        ];
        Aes128::new(key).decrypt_block(&mut block);
        let expected: [u8; 16] = core::array::from_fn(|i| (i as u8) * 0x11);
        assert_eq!(block, expected);
    }

    #[test]
    fn cbc_chains_previous_ciphertext() {
        // NIST SP 800-38A F.2.2 (CBC-AES128.Decrypt), first two blocks, but
        // with a zero IV: the first plaintext is XORed with the real IV here.
        let key = [
            0x2b, 0x7e, 0x15, 0x16, 0x28, 0xae, 0xd2, 0xa6, 0xab, 0xf7, 0x15, 0x88, 0x09, 0xcf,
            0x4f, 0x3c,
        ];
        let iv: [u8; 16] = core::array::from_fn(|i| i as u8);
        let mut data = [
            0x76, 0x49, 0xab, 0xac, 0x81, 0x19, 0xb2, 0x46, 0xce, 0xe9, 0x8e, 0x9b, 0x12, 0xe9,
            0x19, 0x7d, 0x50, 0x86, 0xcb, 0x9b, 0x50, 0x72, 0x19, 0xee, 0x95, 0xdb, 0x11, 0x3a,
            0x91, 0x76, 0x78, 0xb2,
        ];
        Aes128::new(key).decrypt_cbc_zero_iv(&mut data);
        for (b, v) in data[..16].iter_mut().zip(iv) {
            *b ^= v;
        }
        assert_eq!(
            data,
            [
                0x6b, 0xc1, 0xbe, 0xe2, 0x2e, 0x40, 0x9f, 0x96, 0xe9, 0x3d, 0x7e, 0x11, 0x73, 0x93,
                0x17, 0x2a, 0xae, 0x2d, 0x8a, 0x57, 0x1e, 0x03, 0xac, 0x9c, 0x9e, 0xb7, 0x6f, 0xac,
                0x45, 0xaf, 0x8e, 0x51,
            ]
        );
    }
}
